<script setup>
import {ref,computed} from 'vue'
import Icon from './Icon.vue'
import {count,dateLabel,sceneName,modeLabel,signed} from '../dataModel.js'
const props=defineProps({records:{type:Array,default:()=>[]},total:{type:Number,default:0},page:{type:Number,default:1},loading:Boolean,error:String,compact:Boolean,cards:Boolean,pagination:{type:Boolean,default:true},title:{type:String,default:'最近牌谱'},subtitle:{type:String,default:'不受趋势区间影响'},selectedId:String})
defineEmits(['select','page','retry'])
const search=ref('')
const filtered=computed(()=>props.records.filter(r=>`${r.game_id} ${r.players.map(p=>p.username).join(' ')}`.toLowerCase().includes(search.value.toLowerCase().trim())))
const visible=computed(()=>props.compact?filtered.value.slice(0,5):filtered.value)
function exportCSV(){
  const cell=value=>'"'+String(value??'').replace(/"/g,'""').replace(/^([=+@-])/,'\'$1')+'"'
  const rows=[['牌谱编号','时间','场次','模式','玩家','得分','顺位'],...filtered.value.flatMap(r=>r.players.map(p=>[r.game_id,r.created_at,sceneName(r),modeLabel(r.match_type,r.rule),p.username,p.score,p.rank]))]
  const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}))
  const a=document.createElement('a');a.href=url;a.download='当前页牌谱摘要.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
</script>
<template><section class="panel records-panel"><div class="panel-heading"><div><h2>{{title}}</h2><span class="subtle">{{count(total||records.length)}} 场记录 · {{subtitle}}</span></div><button class="icon-button" title="导出当前页摘要 CSV" aria-label="导出当前页摘要 CSV" :disabled="!records.length" @click="exportCSV"><Icon name="download"/></button></div><div v-if="!compact" class="record-toolbar"><label class="search-field"><Icon name="search" :size="16"/><input v-model="search" type="search" placeholder="筛选本页牌谱 / 玩家" aria-label="筛选本页牌谱或玩家"></label><span class="subtle">点击记录查看详情</span></div><div v-if="loading" class="inline-empty" role="status">正在载入牌谱…</div><div v-else-if="error" class="inline-empty error-state">{{error}}<button class="text-button" @click="$emit('retry')">重新载入</button></div><div v-else-if="!visible.length" class="inline-empty">{{search?'本页没有匹配结果':'暂无可展示的牌谱'}}</div><div v-else-if="cards" class="record-cards"><button v-for="record in visible" :key="record.game_id" class="record-card" :class="{active:selectedId===record.game_id}" @click="$emit('select',record)"><div><span class="record-time">{{dateLabel(record.created_at)}}</span><span class="tag">{{sceneName(record)}}</span></div><strong class="mono">{{record.game_id}}</strong><div class="player-scores"><span v-for="p in record.players" :key="p.user_id">{{p.username}}<b :class="{'score-positive':p.score>0}">{{signed(p.score)}}</b></span></div><span class="record-open">{{modeLabel(record.match_type,record.rule)}} <Icon name="arrow" :size="16"/></span></button></div><div v-else class="table-scroll"><table class="record-table"><thead><tr><th>时间 / 编号</th><th>场次</th><th>对局玩家</th><th v-if="!compact">模式</th><th><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="record in visible" :key="record.game_id" :class="{active:selectedId===record.game_id}"><td><span class="record-time">{{dateLabel(record.created_at)}}</span><button class="record-id" @click="$emit('select',record)">{{record.game_id}}</button></td><td><span class="tag">{{sceneName(record)}}</span></td><td><div class="players-inline"><span v-for="p in record.players" :key="p.user_id" :title="p.username+' · '+signed(p.score)+' · '+p.rank+' 位'">{{p.username}}</span></div></td><td v-if="!compact" class="nowrap">{{modeLabel(record.match_type,record.rule)}}</td><td><button class="icon-button" :aria-label="'查看牌谱 '+record.game_id" @click="$emit('select',record)"><Icon name="arrow" :size="17"/></button></td></tr></tbody></table></div><div v-if="pagination&&!compact&&total>12" class="pagination"><span>第 {{page}} / {{Math.ceil(total/12)}} 页</span><div><button :disabled="page<=1||loading" @click="$emit('page',page-1)">上一页</button><button :disabled="page*12>=total||loading" @click="$emit('page',page+1)">下一页</button></div></div></section></template>
